rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /c_literal_ne/{doc} {
      allow get: if /a/b != /a/c;
    }
    match /c_interpolate/{doc} {
      allow get: if /databases/$(database)/documents/c_interpolate/$(doc) == request.path;
    }
    match /c_interpolate_slash/{doc} {
      allow get: if /a/$('b/c')/d == /a/b/c/d;
    }
    match /c_interpolate_slash_size/{doc} {
      allow get: if /a/$('b/c')/d[1] == 'b/c';
    }
    match /c_interpolate_int/{doc} {
      allow get: if /a/$(1) == /a/1;
    }
    match /c_path_fn_relative/{doc} {
      allow get: if path('a/b') == /a/b;
    }
    match /c_path_index/{doc} {
      allow get: if /a/b/c[1] == 'b';
    }
    match /c_path_index_out_of_range/{doc} {
      allow get: if /a/b[5] == 'x';
    }
    match /c_path_eq_string/{doc} {
      allow get: if /a/b == '/a/b';
    }
    match /c_path_string/{doc} {
      allow get: if string(/a/b) == '/a/b';
    }
    match /c_path_concat/{doc} {
      allow get: if /a/b + '/c' == '/a/b/c';
    }
    match /c_request_path_index/{doc} {
      allow get: if request.path[3] == 'c_request_path_index';
    }
    match /c_request_path_tail/{doc} {
      allow get: if request.path[4] == 'doc';
    }
    match /c_path_is_path/{doc} {
      allow get: if /a/b is path;
    }
    match /c_path_in/{doc} {
      allow get: if 'b' in /a/b;
    }
    match /c_path_special_chars/{doc} {
      allow get: if /a/$('b c')/d[1] == 'b c';
    }
    match /c_path_encoded_segment/{doc} {
      allow get: if /a/b%20c[1] == 'b c';
    }
    match /c_path_dot_segment/{doc} {
      allow get: if /a/b.c[1] == 'b.c';
    }
    match /c_path_dash_segment/{doc} {
      allow get: if /a/b-c[1] == 'b-c';
    }
    match /c_path_parens_segment/{doc} {
      allow get: if /databases/(default)/documents[1] == '(default)';
    }
  }
}

